import math

def mi_as_kl(joint):
    """I(X; Y) in bits as D(joint || product of margins), from chances or counts."""
    total = sum(sum(row) for row in joint)
    p = [[c / total for c in row] for row in joint]
    px = [sum(row) for row in p]
    py = [sum(col) for col in zip(*p)]
    out = 0.0
    for i, row in enumerate(p):
        for j, c in enumerate(row):
            if c > 0:
                out += c * math.log2(c / (px[i] * py[j]))
    return out

